import os
from logging import Logger
from typing import Literal

from huggingface_hub import snapshot_download
from huggingface_hub.errors import LocalEntryNotFoundError

# Filenames that indicate a repository snapshot actually contains the model
# weights (as opposed to only config/tokenizer files left over from a
# previous, incomplete download).
_MODEL_WEIGHT_FILE_NAMES = {
    "model.safetensors",
    "model.safetensors.index.json",
    "pytorch_model.bin",
    "pytorch_model.bin.index.json",
}


class ModelRepositories:


    def update(self):
        # TODO collect model information from presets
        pass

    @staticmethod
    def _has_model_weights(path: str) -> bool:
        for _, _, files in os.walk(path):
            if _MODEL_WEIGHT_FILE_NAMES & set(files):
                return True
        return False

    @classmethod
    def get_or_download(self, mode_id: str, model_path: str | None = None, logger: Logger | None = None,
                        provider: Literal['hf'] = 'hf') -> str:
        if mode_id == 'test-model':
            # For testing purpose only
            return mode_id

        # TODO capture download progress and pass to MQ
        try:
            path = snapshot_download(mode_id, local_dir=model_path, local_files_only=True)
            if logger:
                logger.info(f"{mode_id} already present at {path}")
            if not self._has_model_weights(path):
                if logger:
                    logger.info(
                        f"{mode_id} present at {path} but missing model weight files, "
                        f"downloading missing files..."
                    )
                path = snapshot_download(mode_id, local_dir=model_path)
        except LocalEntryNotFoundError:
            if logger:
                logger.info(f"{mode_id} not found locally, downloading...")
            path = snapshot_download(mode_id, local_dir=model_path)
        return path
